	public void InvalidNumericModesKeepControlledEscapeByteDiagnostics( string pattern, int mode, int offset ) {
		var options = Options( mode ); Assert.Throws<PcrePatternException>( () => Reference( pattern, mode, options ) );
		var result = PcreByteCompiler.Compile( Encoding.UTF8.GetBytes( pattern ), options ); Assert.Null( result.Pattern );
		Assert.Equal( PcreByteDiagnosticCode.InvalidSyntax, result.Diagnostic?.Code ); Assert.Equal( offset, result.Diagnostic?.ByteOffset );
	}

	[Theory]
	[InlineData( 0, false )]
	[InlineData( 0, true )]
	[InlineData( 1, false )]
	[InlineData( 1, true )]
