	[InlineData( 3, true )]
	[InlineData( 4, false )]
	[InlineData( 4, true )]
	[InlineData( 5, false )]
	[InlineData( 5, true )]
	[InlineData( 6, false )]
	[InlineData( 6, true )]
	[InlineData( 7, false )]
	[InlineData( 7, true )]
	public void EveryOctetKeepsThreeDigitOctalAndBracedForms( int mode, bool bracket ) {
		var options = Options( mode );
		for ( var value = 0; value < 256; value++ ) {
			foreach ( var atom in new[] { String.Concat( "\\", Convert.ToString( value, 8 ).PadLeft( 3, '0' ) ), String.Concat( @"\o{", Convert.ToString( value, 8 ), "}" ) } ) {
				var pattern = bracket ? String.Concat( "[", atom, "]" ) : atom; var subject = options.Utf8 ? Encoding.UTF8.GetBytes( char.ConvertFromUtf32( value ) ) : new[] { (byte)value };
				var reference = Reference( pattern, mode, options ); AssertLiteral( reference, subject, $"0:{subject.Length}" ); Compare( reference, subject, 0, Compile( pattern, options ).Match( subject ), pattern );
			}
		}
	}

	[Theory]
	[InlineData( false )]
	[InlineData( true )]
	public void SelectedOffsetsRetainUtfFragmentsCrLfAndLookbehindReferences( bool anyCrLf ) {
		foreach ( var mode in new[] { 4, 5, 6, 7 } ) {
			var options = Options( mode ) with { MatchInvalidUtf = true, AnyCrLfNewline = anyCrLf };
			foreach ( var body in new[] { @"(\00?)\1", @"[\000-\377]+", @"(?=\101)\101", @"(?<=\101)(a)", @"\o{351}+", String.Concat( String.Concat( Enumerable.Repeat( "()", 11 ) ), @"(a)(?<=\12)b" ) } ) {
				var reference = Reference( body, mode, options ); var compiled = Compile( body, options );
				foreach ( var hex in new[] { "", "0000FF00", "0D0A4161", "FFC3A9FF", "C3FFC3A9", "6162" } ) {
					var subject = Convert.FromHexString( hex ); for ( var offset = 0; offset <= subject.Length; offset++ ) { Compare( reference, subject, offset, compiled.Match( subject, offset ), $"{mode}/{body}/{hex}/{offset}" ); }
				}
			}
		}
	}

	[Fact]
	public void NumericPoliciesAreCapturedPerCompilationWithOwnedSource() {
		var pattern = String.Concat( String.Concat( Enumerable.Repeat( "()", 99 ) ), @"(a)\100" ); var source = Encoding.ASCII.GetBytes( pattern ); var options = Options( 1 );
		var result = PcreByteCompiler.Compile( source, options ); Assert.True( result.IsSuccess ); Array.Fill( source, (byte)'x' ); SetPolicy( options, "PythonOctal", false );
		var defaultPeer = Compile( pattern, Options( 0 ) );
		foreach ( var ignored in Enumerable.Range( 0, 3 ) ) { Assert.NotNull( result.Pattern!.Match( "a@"u8.ToArray() ).Match ); Assert.Null( result.Pattern.Match( "aa"u8.ToArray() ).Match ); Assert.NotNull( defaultPeer.Match( "aa"u8.ToArray() ).Match ); Assert.Null( defaultPeer.Match( "a@"u8.ToArray() ).Match ); }
	}

	[Fact]
	public void LongRunsKeepBoundedScansWorkAndCancellation() {
		foreach ( var mode in new[] { 1, 3, 5, 7 } ) {
			var pattern = String.Concat( "\\", new string( '1', 512 ) ); var subject = Encoding.ASCII.GetBytes( String.Concat( "I", new string( '1', 509 ) ) ); var steps = new List<int>(); var options = Options( mode ); var reference = Reference( pattern, mode, options ); AssertLiteral( reference, subject, "0:510" );
			Compare( reference, subject, 0, Compile( pattern, options with { WorkObserver = steps.Add } ).Match( subject ), "long octal" ); Assert.Equal( Enumerable.Range( 1, steps.Count ), steps );
			var limited = Compile( pattern, options with { MatchWorkLimit = steps.Count - 1 } ).Match( subject ); Assert.Null( limited.Match ); Assert.Equal( PcreByteDiagnosticCode.MatchWorkLimitExceeded, limited.Diagnostic?.Code );
			using var cancellation = new CancellationTokenSource(); var cancellable = Compile( pattern, options with { WorkObserver = count => { if ( count == 4 ) { cancellation.Cancel(); } } } ); Assert.Throws<OperationCanceledException>( () => cancellable.Match( subject, cancellationToken: cancellation.Token ) ); Assert.Throws<OperationCanceledException>( () => PcreByteCompiler.Compile( Encoding.ASCII.GetBytes( pattern ), options, cancellation.Token ) );
			var decimalRun = PcreByteCompiler.Compile( Encoding.ASCII.GetBytes( String.Concat( "\\", new string( '8', 512 ) ) ), options ); Assert.Equal( PcreByteDiagnosticCode.InvalidSyntax, decimalRun.Diagnostic?.Code ); Assert.Equal( 0, decimalRun.Diagnostic?.ByteOffset );
		}
	}

	[Fact]
	public void PoliciesKeepResourceCeilingsAndDoNotInventDirectives() {
		var options = Options( 3 ); var tooMany = PcreByteCompiler.Compile( Encoding.ASCII.GetBytes( String.Concat( Enumerable.Repeat( "()", 257 ) ) ), options ); Assert.Equal( PcreByteDiagnosticCode.PatternCaptureLimitExceeded, tooMany.Diagnostic?.Code );
		var expanded = PcreByteCompiler.Compile( Encoding.ASCII.GetBytes( @"\101{4096}" ), options ); Assert.Equal( PcreByteDiagnosticCode.PatternRepeatLimitExceeded, expanded.Diagnostic?.Code );
		foreach ( var pattern in new[] { "(*PYTHON_OCTAL)", "(*NO_BS0)" } ) { Assert.Throws<PcrePatternException>( () => Reference( pattern, 3, options ) ); Assert.Equal( PcreByteDiagnosticCode.UnsupportedSyntax, PcreByteCompiler.Compile( Encoding.ASCII.GetBytes( pattern ), options ).Diagnostic?.Code ); }
	}

	// Reflection lets this tests-first commit compile before the new internal options exist.
	private static PcreByteOptions Options( int mode ) {
		var options = new PcreByteOptions { Utf8 = ( mode & 4 ) != 0, Ucp = ( mode & 4 ) != 0, AltExtendedClass = ( mode & 8 ) != 0 }; SetPolicy( options, "PythonOctal", ( mode & 1 ) != 0 ); SetPolicy( options, "NoBackslashZero", ( mode & 2 ) != 0 ); return options;
	}
	private static void SetPolicy( PcreByteOptions options, string name, bool value ) => typeof( PcreByteOptions ).GetProperty( name )?.SetValue( options, value );
	private static ReadOnlyMemory<byte> Mark( PcreByteMatch match ) => match.MarkName;

	private static void AssertLiteral( PcreRegex8Bit reference, byte[] subject, string spans ) {
		var match = reference.Match( subject );
		Assert.Equal( spans.Length > 0, match.Success );
		if ( !match.Success ) { return; }
		var groups = spans.Split( ',' );
		Assert.Equal( groups.Length, match.Groups.Count );
		for ( var group = 0; group < groups.Length; group++ ) {
			var capture = match.Groups[group];
			Assert.Equal( groups[group], capture.Success ? $"{capture.Index}:{capture.Length}" : "-" );
		}
	}

	private static void Compare( PcreRegex8Bit reference, byte[] subject, int offset, PcreByteMatchResult actual, string context ) {
		var expected = reference.Match( subject, offset );
		Assert.True( actual.IsSuccess, $"{context}: {actual.Diagnostic?.Message}" );
		Assert.True( ( expected.Success ? expected.Index : -1 ) == ( actual.Match?.ByteIndex ?? -1 ), context );
		if ( !expected.Success ) { return; }
		Assert.Equal( expected.Mark.ToArray(), Mark( actual.Match! ).ToArray() );
		Assert.Equal( expected.Length, actual.Match!.ByteLength );
		Assert.Equal( expected.Groups.Count, actual.Match.Captures.Count );
		for ( var group = 0; group < expected.Groups.Count; group++ ) {
			var capture = expected.Groups[group];
			Assert.Equal( capture.Success ? new PcreByteCapture( capture.Index, capture.Length ) : null, actual.Match.Captures[group] );
		}
	}

	private static PcreRegex8Bit Reference( string pattern, int mode, PcreByteOptions options ) => new( Encoding.UTF8.GetBytes( pattern ), Encoding.UTF8, new PcreRegexSettings {
		Options = PcreOptions.Compiled | ( options.Utf8 || options.MatchInvalidUtf ? PcreOptions.Utf : PcreOptions.None ) | ( options.Ucp ? PcreOptions.Ucp : PcreOptions.None ) | ( options.MatchInvalidUtf ? PcreOptions.MatchInvalidUtf : PcreOptions.None ) | ( options.AltExtendedClass ? (PcreOptions)0x08000000 : PcreOptions.None ),
		ExtraCompileOptions = (PcreExtraCompileOptions)( ( mode & 1 ) != 0 ? 0x2000 : 0 ) | (PcreExtraCompileOptions)( ( mode & 2 ) != 0 ? 0x4000 : 0 ),
		NewLine = options.AnyCrLfNewline ? PcreNewLine.AnyCrLf : PcreNewLine.Lf, ParensLimit = 512
	} );

	private static PcreCompiledBytePattern Compile( string pattern, PcreByteOptions options ) {
		var result = PcreByteCompiler.Compile( Encoding.UTF8.GetBytes( pattern ), options );
		Assert.True( result.IsSuccess, $"{pattern}: {result.Diagnostic?.Message}" );
		return Assert.IsType<PcreCompiledBytePattern>( result.Pattern );
	}
